uv run python - <<'EOF'
import ast
src = open("tests/test_cache_contract.py").read()
tree = ast.parse(src)
counts = {}
for node in tree.body:
    if isinstance(node, ast.FunctionDef) and node.name.startswith("test_"):
        steps = [d.args[0].value for d in node.decorator_list
                 if isinstance(d, ast.Call) and getattr(d.func, "id", None) == "step"]
        cases = 1
        for d in node.decorator_list:
            if isinstance(d, ast.Call) and getattr(getattr(d.func, "attr", None), "__str__", None) and getattr(d.func, "attr", "") == "parametrize":
                cases = len(d.args[1].elts)
        counts[steps[0] if steps else 0] = counts.get(steps[0] if steps else 0, 0) + cases
print(dict(sorted(counts.items())), "total", sum(counts.values()))
EOF

